const fs = require\('fs'\)
const lines = fs.readFileSync\('csv/Products.csv','utf-8'\).trim\(\).split\('\\n'\)
// Header: Order ID;Category;Product;SKU;Qty;Price;Net sale;Profit;Profit %
const prodCost = new Map\(\) // product name -> cost per unit
for\(let i=1;i<lines.length;i++\){
  const cols = lines[i].split\(';'\)
  const name = cols[2]?.trim\(\)
  const qty = parseInt\(cols[4]\) || 0
  const netSale = parseFloat\(cols[6]?.replace\(',','.'\)\) || 0
  const profit = parseFloat\(cols[7]?.replace\(',','.'\)\) || 0
  if\(!name || qty === 0\) continue
  const costTotal = netSale - profit
  const costPerUnit = costTotal / qty
  if\(!prodCost.has\(name\) || costPerUnit > 0\){
    prodCost.set\(name, { costPerUnit: Math.round\(costPerUnit*100\), price: Math.round\(\(netSale/qty\)*100\), name }\)
  }
}
console.log\('Products with cost:', prodCost.size\)
let shown = 0
for\(const [name, info] of prodCost\){
  if\(shown++ < 10\) console.log\('  ' + name + ' | cost: €' + \(info.costPerUnit/100\).toFixed\(2\) + ' | price: €' + \(info.price/100\).toFixed\(2\)\)
}
