// Fixed parsePrice
function parsePrice\(v\){
  if\(!v||v===''\)return 0
  let s=String\(v\).trim\(\)
  // Dutch format: 1.234,56 — dot is thousand sep, comma is decimal
  if\(s.includes\(','\) && s.includes\('.'\)\) s = s.replace\(/\\./g,''\).replace\(',','.'\)
  // Only comma, no dot: comma is decimal \(e.g. 5,75\)
  else if\(s.includes\(','\) && !s.includes\('.'\)\) s = s.replace\(',','.'\)
  // Only dot: it's already decimal \(e.g. 228.90\) — don't remove!
  return parseFloat\(s\)||0
}
function eurToCents\(v\){return Math.round\(parsePrice\(v\)*100\)}
